package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"

	"github.com/minhquan2904/loki-via-grafana-mcp/internal/redact"
)

// Markers around the benchmark table inside README.md; everything else in the
// file is preserved byte for byte.
const (
	benchStart = "<!-- BENCH:START -->"
	benchEnd   = "<!-- BENCH:END -->"
)

// docHeader opens the generated docs/benchmarks.md.
const docHeader = "# Benchmarks\n\n" +
	"Generated by `cmd/benchreport` from a `cmd/bench` run; do not edit by hand.\n\n"

type row struct {
	Target             string  `json:"target"`
	Scenario           string  `json:"scenario"`
	Concurrency        int     `json:"concurrency"`
	N                  int     `json:"n"`
	Errors             int     `json:"errors"`
	Throttled          int     `json:"throttled"`
	P50MS              float64 `json:"p50_ms"`
	P95MS              float64 `json:"p95_ms"`
	MaxMS              float64 `json:"max_ms"`
	RPS                float64 `json:"rps"`
	RespBytesP50       float64 `json:"resp_bytes_p50"`
	PointsPerSeriesMax int     `json:"points_per_series_max"`
	LinesP50           float64 `json:"lines_p50"`
}

type meta struct {
	CPUModel      string  `json:"cpu_model"`
	VCPU          int     `json:"vcpu"`
	RAMGB         float64 `json:"ram_gb"`
	OS            string  `json:"os"`
	DockerVersion string  `json:"docker_version"`
	GoVersion     string  `json:"go_version"`
	GoSDKVersion  string  `json:"gosdk_version"`
	Commit        string  `json:"commit"`
	Timestamp     string  `json:"timestamp"`
}

type extra struct {
	ImageSizeMB map[string]float64            `json:"image_size_mb"`
	ColdStartMS map[string]float64            `json:"cold_start_ms"`
	RSSMB       map[string]map[string]float64 `json:"rss_mb"`
}

// scenarios in report order, with the note the contract asks for.
var scenarioNotes = map[string]string{
	"S0": "fake Grafana — server overhead only",
	"S1": "real Grafana Cloud Loki",
	"S2": "real Grafana Cloud Loki",
	"S3": "real Grafana Cloud Loki",
	"S4": "real Grafana Cloud Loki",
}

var scenarioOrder = []string{"S0", "S1", "S2", "S3", "S4"}

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

func run(args []string, stdout, stderr io.Writer) int {
	flags := flag.NewFlagSet("benchreport", flag.ContinueOnError)
	flags.SetOutput(stderr)
	rowsPath := flags.String("rows", "", "rows.jsonl produced by cmd/bench")
	metaPath := flags.String("meta", "", "meta.json produced by cmd/bench")
	extraPath := flags.String("extra", "", "extra.json produced by cmd/bench")
	readmePath := flags.String("readme", "", "README.md to update between the bench markers")
	docPath := flags.String("doc", "", "docs/benchmarks.md to write")
	redactFile := flags.String("redact-file", "", "extra deny patterns, one regular expression per line")
	printDenylist := flags.Bool("print-denylist", false, "print the deny patterns one per line and exit 0")

	if err := flags.Parse(args); err != nil {
		return 2
	}

	denylist := redact.Default()
	if *redactFile != "" {
		if err := denylist.WithFile(*redactFile); err != nil {
			fmt.Fprintln(stderr, "benchreport:", err)
			return 2
		}
	}

	// Single source of the patterns for scripts/denylist-scan.sh. The local
	// .denylist.local file is deliberately not read here: the scanner adds it.
	if *printDenylist {
		for _, pattern := range denylist.Patterns() {
			fmt.Fprintln(stdout, pattern)
		}
		return 0
	}

	for name, value := range map[string]string{
		"-rows": *rowsPath, "-meta": *metaPath, "-extra": *extraPath,
		"-readme": *readmePath, "-doc": *docPath,
	} {
		if value == "" {
			fmt.Fprintf(stderr, "benchreport: %s is required\n", name)
			return 2
		}
	}

	rows, err := readRows(*rowsPath)
	if err != nil {
		fmt.Fprintln(stderr, "benchreport:", err)
		return 2
	}
	var metaDoc meta
	if err := readJSON(*metaPath, &metaDoc); err != nil {
		fmt.Fprintln(stderr, "benchreport:", err)
		return 2
	}
	var extraDoc extra
	if err := readJSON(*extraPath, &extraDoc); err != nil {
		fmt.Fprintln(stderr, "benchreport:", err)
		return 2
	}

	if err := refuseSensitive(rows, metaDoc, extraDoc, denylist); err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}

	body := render(rows, metaDoc, extraDoc)

	if err := replaceBetweenMarkers(*readmePath, body); err != nil {
		fmt.Fprintln(stderr, "benchreport:", err)
		return 1
	}
	if err := os.WriteFile(*docPath, []byte(docHeader+body), 0o644); err != nil {
		fmt.Fprintln(stderr, "benchreport:", err)
		return 2
	}
	return 0
}

func readRows(path string) ([]row, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("reading rows: %w", err)
	}
	var rows []row
	for i, line := range strings.Split(string(raw), "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		var entry row
		if err := json.Unmarshal([]byte(line), &entry); err != nil {
			return nil, fmt.Errorf("rows line %d: %w", i+1, err)
		}
		rows = append(rows, entry)
	}
	if len(rows) == 0 {
		return nil, errors.New("rows file holds no rows")
	}
	return rows, nil
}

func readJSON(path string, into any) error {
	raw, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("reading %s: %w", path, err)
	}
	if err := json.Unmarshal(raw, into); err != nil {
		return fmt.Errorf("%s: %w", path, err)
	}
	return nil
}

// refuseSensitive walks every string in the inputs and stops at the first one
// that matches a deny pattern or carries a non-loopback address. The message
// names the field, never the value.
func refuseSensitive(rows []row, metaDoc meta, extraDoc extra, denylist *redact.Denylist) error {
	docs := []struct {
		name  string
		value any
	}{
		{"meta", metaDoc},
		{"extra", extraDoc},
	}
	for _, doc := range docs {
		raw, err := json.Marshal(doc.value)
		if err != nil {
			return fmt.Errorf("benchreport: %w", err)
		}
		var generic any
		if err := json.Unmarshal(raw, &generic); err != nil {
			return fmt.Errorf("benchreport: %w", err)
		}
		if path, found := findSensitive(generic, doc.name, denylist); found {
			return fmt.Errorf("refusing to publish: field %s matches a denied pattern", path)
		}
	}

	for i, entry := range rows {
		raw, err := json.Marshal(entry)
		if err != nil {
			return fmt.Errorf("benchreport: %w", err)
		}
		var generic any
		if err := json.Unmarshal(raw, &generic); err != nil {
			return fmt.Errorf("benchreport: %w", err)
		}
		if path, found := findSensitive(generic, "rows["+strconv.Itoa(i)+"]", denylist); found {
			return fmt.Errorf("refusing to publish: field %s matches a denied pattern", path)
		}
	}
	return nil
}

func findSensitive(value any, path string, denylist *redact.Denylist) (string, bool) {
	switch typed := value.(type) {
	case map[string]any:
		keys := make([]string, 0, len(typed))
		for key := range typed {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			if found, ok := findSensitive(typed[key], path+"."+key, denylist); ok {
				return found, true
			}
		}
	case []any:
		for i, item := range typed {
			if found, ok := findSensitive(item, path+"["+strconv.Itoa(i)+"]", denylist); ok {
				return found, true
			}
		}
	case string:
		if _, ok := denylist.Match(typed); ok {
			return path, true
		}
		if redact.IsPrivateIP(typed) {
			return path, true
		}
	}
	return "", false
}

// render builds the markdown that goes between the markers and into
// docs/benchmarks.md.
func render(rows []row, metaDoc meta, extraDoc extra) string {
	var out strings.Builder

	out.WriteString("| Scenario | Go p50 / p95 (ms) | Python p50 / p95 (ms) | Go errors | Python errors | Notes |\n")
	out.WriteString("|---|---|---|---|---|---|\n")
	for _, scenario := range scenarioOrder {
		goRow, hasGo := findRow(rows, "go", scenario)
		pyRow, hasPy := findRow(rows, "python", scenario)
		if !hasGo && !hasPy {
			continue
		}
		out.WriteString("| " + scenario + " | " + latency(goRow, hasGo) + " | " + latency(pyRow, hasPy) +
			" | " + errorsOf(goRow, hasGo) + " | " + errorsOf(pyRow, hasPy) +
			" | " + scenarioNotes[scenario] + " |\n")
	}

	out.WriteString("\n| Metric | Go | Python |\n|---|---|---|\n")
	out.WriteString("| Image size (MB) | " + megabytes(extraDoc.ImageSizeMB, "go") + " | " + megabytes(extraDoc.ImageSizeMB, "python") + " |\n")
	out.WriteString("| Cold start to /healthz (ms) | " + milliseconds(extraDoc.ColdStartMS, "go") + " | " + milliseconds(extraDoc.ColdStartMS, "python") + " |\n")
	out.WriteString("| RSS idle (MB) | " + rss(extraDoc.RSSMB, "go", "idle") + " | " + rss(extraDoc.RSSMB, "python", "idle") + " |\n")
	out.WriteString("| RSS peak under S4 (MB) | " + rss(extraDoc.RSSMB, "go", "peak") + " | " + rss(extraDoc.RSSMB, "python", "peak") + " |\n")
	out.WriteString("| S3 points per series | " + points(rows, "go") + " | " + points(rows, "python") + " |\n")
	out.WriteString("| S3 response size (KB) | " + responseKB(rows, "go") + " | " + responseKB(rows, "python") + " |\n")

	out.WriteString("\nMeasured on " + strconv.Itoa(metaDoc.VCPU) + " vCPU " + metaDoc.CPUModel + ", " +
		trimFloat(metaDoc.RAMGB) + " GB RAM, against a Loki datasource on Grafana Cloud, commit " +
		shortCommit(metaDoc.Commit) + ", " + metaDoc.Timestamp + ". " +
		"Python = the FastMCP reference implementation this project replaces. Full report: docs/benchmarks.md\n")

	return out.String()
}

func findRow(rows []row, target, scenario string) (row, bool) {
	for _, entry := range rows {
		if entry.Target == target && entry.Scenario == scenario {
			return entry, true
		}
	}
	return row{}, false
}

func latency(entry row, ok bool) string {
	if !ok {
		return "—"
	}
	return trimFloat(entry.P50MS) + " / " + trimFloat(entry.P95MS)
}

func errorsOf(entry row, ok bool) string {
	if !ok {
		return "—"
	}
	if entry.Throttled > 0 {
		return strconv.Itoa(entry.Errors) + " (" + strconv.Itoa(entry.Throttled) + " throttled)"
	}
	return strconv.Itoa(entry.Errors)
}

func megabytes(values map[string]float64, key string) string {
	value, ok := values[key]
	if !ok {
		return "—"
	}
	return trimFloat(value)
}

func milliseconds(values map[string]float64, key string) string {
	value, ok := values[key]
	if !ok {
		return "—"
	}
	return trimFloat(value)
}

func rss(values map[string]map[string]float64, target, kind string) string {
	perTarget, ok := values[target]
	if !ok {
		return "—"
	}
	value, ok := perTarget[kind]
	if !ok {
		return "—"
	}
	return trimFloat(value)
}

func points(rows []row, target string) string {
	entry, ok := findRow(rows, target, "S3")
	if !ok {
		return "—"
	}
	return strconv.Itoa(entry.PointsPerSeriesMax)
}

func responseKB(rows []row, target string) string {
	entry, ok := findRow(rows, target, "S3")
	if !ok {
		return "—"
	}
	return trimFloat(entry.RespBytesP50 / 1024)
}

func trimFloat(value float64) string {
	return strconv.FormatFloat(value, 'f', -1, 64)
}

func shortCommit(commit string) string {
	if len(commit) > 12 {
		return commit[:12]
	}
	return commit
}

// replaceBetweenMarkers swaps the text between the bench markers and leaves
// every other byte of the file alone.
func replaceBetweenMarkers(path, body string) error {
	raw, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("reading %s: %w", path, err)
	}
	start := bytes.Index(raw, []byte(benchStart))
	if start < 0 {
		return fmt.Errorf("%s is missing %s", path, benchStart)
	}
	searchFrom := start + len(benchStart)
	end := bytes.Index(raw[searchFrom:], []byte(benchEnd))
	if end < 0 {
		return fmt.Errorf("%s is missing %s", path, benchEnd)
	}
	end += searchFrom

	var updated bytes.Buffer
	updated.Write(raw[:start+len(benchStart)])
	updated.WriteString("\n")
	updated.WriteString(body)
	updated.Write(raw[end:])

	return os.WriteFile(path, updated.Bytes(), 0o644)
}
